-- =====================================================================
-- seed-base.sql — 기본 더미 데이터(계정·센터·등급·요금정책)
-- seed.ts(ts-node) 산출을 SQL로 덤프(column-inserts) — 런타임 컨테이너(ts-node 없음)에서도
-- psql 로 바로 주입 가능. 더미 로그인 7종 · 공통 비번: dev-password!
-- 사용: docker compose ... exec -T postgres psql -U itall -d itall < prisma/seed-base.sql
-- 멱등 아님 — 빈 DB 1회 주입 권장.
-- =====================================================================
BEGIN;
SET session_replication_role = replica;  -- FK/트리거 우회(주입 순서 무관)
-- 데모: 학부모(guardian01) ↔ 자녀(student01) 연결 — 학부모 화면/리포트에 데이터가 보이도록.
VALUES ('00000000-0000-4000-8000-0000000000e1', '00000000-0000-4000-8000-0000000000a5', '00000000-0000-4000-8000-0000000000a1', '부모', 'approved', 'seed')
ON CONFLICT (guardian_id, student_id) DO NOTHING;

SET session_replication_role = origin;
COMMIT;
